import{_ as t,H as i,f as E,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"18 | CKA认证考试报名流程及注意事项","description":"","frontmatter":{},"headers":[{"level":2,"title":"购买 CKA 考试券","slug":"购买-cka-考试券","link":"#购买-cka-考试券","children":[{"level":3,"title":"实名认证","slug":"实名认证","link":"#实名认证","children":[]},{"level":3,"title":"购买考试券","slug":"购买考试券","link":"#购买考试券","children":[]},{"level":3,"title":"查看考试券","slug":"查看考试券","link":"#查看考试券","children":[]}]},{"level":2,"title":"注册 CKA 考试","slug":"注册-cka-考试","link":"#注册-cka-考试","children":[{"level":3,"title":"注册 Linux 基金会 ID","slug":"注册-linux-基金会-id","link":"#注册-linux-基金会-id","children":[]},{"level":3,"title":"使用考试券注册考试","slug":"使用考试券注册考试","link":"#使用考试券注册考试","children":[]}]},{"level":2,"title":"预约 CKA 考试","slug":"预约-cka-考试","link":"#预约-cka-考试","children":[{"level":3,"title":"信息验证","slug":"信息验证","link":"#信息验证","children":[]},{"level":3,"title":"预约考试时间","slug":"预约考试时间","link":"#预约考试时间","children":[]},{"level":3,"title":"常见预约问题","slug":"常见预约问题","link":"#常见预约问题","children":[]}]},{"level":2,"title":"考试前注意事项","slug":"考试前注意事项","link":"#考试前注意事项","children":[]},{"level":2,"title":"考试中注意事项","slug":"考试中注意事项","link":"#考试中注意事项","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"零基础拿下云原生CKA认证/18｜CKA认证考试报名流程及注意事项.md","filePath":"零基础拿下云原生CKA认证/18｜CKA认证考试报名流程及注意事项.md","lastUpdated":1795561650000}'),a={name:"零基础拿下云原生CKA认证/18｜CKA认证考试报名流程及注意事项.md"};function s(r,e,B,o,A,l){return i(),E("div",null,[...e[0]||(e[0]=[n('<h1 id="_18-cka认证考试报名流程及注意事项" tabindex="-1">18 | CKA认证考试报名流程及注意事项 <a class="header-anchor" href="#_18-cka认证考试报名流程及注意事项" aria-label="Permalink to &quot;18 | CKA认证考试报名流程及注意事项&quot;">​</a></h1><p>你好，我是雪飞。</p><p>我们已经完成了 CKA 考试知识点的讲解与学习，相信你已经为考试磨刀霍霍了。为了让你更顺利的报名和通过考试，今天我就带你了解一下报名认证考试的流程和考试的注意事项。</p><p>报名 CKA 考试有三个大步骤：首先是要购买 CKA 考试券，然后使用考试券注册考试，最后是预约考试。</p><h2 id="购买-cka-考试券" tabindex="-1">购买 CKA 考试券 <a class="header-anchor" href="#购买-cka-考试券" aria-label="Permalink to &quot;购买 CKA 考试券&quot;">​</a></h2><h3 id="实名认证" tabindex="-1">实名认证 <a class="header-anchor" href="#实名认证" aria-label="Permalink to &quot;实名认证&quot;">​</a></h3><p>在购买 CKA 考试券前，你需要先在开源软件学园（Linux Foundation）的官方网站申请账号，并且通过实名认证。（官网链接：<a href="https://training.linuxfoundation.cn/login%EF%BC%89" target="_blank" rel="noreferrer">https://training.linuxfoundation.cn/login）</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/1.png" alt=""></a></p><p>注册并登录你的个人账号，然后前往“个人中心”，点击“实名认证”。在页面上填写个人身份信息，点击“获取验证码”并到邮箱中查看验证码。最后，输入验证码点击“认证”按钮完成实名认证。（个人中心链接：<a href="https://training.linuxfoundation.cn/member/center%EF%BC%89" target="_blank" rel="noreferrer">https://training.linuxfoundation.cn/member/center）</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/2.png" alt=""></a></p><h3 id="购买考试券" tabindex="-1">购买考试券 <a class="header-anchor" href="#购买考试券" aria-label="Permalink to &quot;购买考试券&quot;">​</a></h3><p>实名认证后，进入网站首页，找到 CKA 认证，点击“获取证书”，进入“证书详情”页面。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/3.png" alt=""></a></p><p>点击“立即购买”，选择“考试模式”（可以在这里选择监考官的语言：中文或英文），建议选择“线上考试 - 中文监考官”，然后进入付款页面。（报名链接：<a href="https://training.linuxfoundation.cn/certificates/1%EF%BC%89" target="_blank" rel="noreferrer">https://training.linuxfoundation.cn/certificates/1）</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/4.png" alt=""></a></p><p>CKA 的考试费用在 “618”、“双十一”、“黑色星期五”等国内外购物节时会有限时优惠。最便宜的就是美国的“黑色星期五”购物节，购买价格可能达到半价优惠。如果你没有在活动时购买考试，也可以联系课程老师给你提供购买优惠码，会有一定的折扣。</p><p>在付款页面中选择“支付方式”，然后支付考试费用。注意：如果有优惠码，请在付款页面的“使用优惠码” 输入框内填写。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/5.png" alt=""></a></p><h3 id="查看考试券" tabindex="-1">查看考试券 <a class="header-anchor" href="#查看考试券" aria-label="Permalink to &quot;查看考试券&quot;">​</a></h3><p>支付成功后就完成了考试券的购买，然后你需要查看考试券号码并使用该号码去注册考试。</p><p>前往“个人中心”，在“考试中心”点击“我的考试”菜单按钮，展示已购买的考试券列表。</p><p>注意：考试券自购买之日起的 30 天内有效，请尽快使用考试券注册考试，注册考试成功之后，你可以预约 12 个月内的任意时间考试。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/6.png" alt=""></a></p><p>在考试券列表中找到 CKA，点击“查看考试券”，并输入官网登录密码，就可以查看考试券号码。之后就可以使用该考试码去注册考试。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/7.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/8.png" alt=""></a></p><h2 id="注册-cka-考试" tabindex="-1">注册 CKA 考试 <a class="header-anchor" href="#注册-cka-考试" aria-label="Permalink to &quot;注册 CKA 考试&quot;">​</a></h2><h3 id="注册-linux-基金会-id" tabindex="-1">注册 Linux 基金会 ID <a class="header-anchor" href="#注册-linux-基金会-id" aria-label="Permalink to &quot;注册 Linux 基金会 ID&quot;">​</a></h3><p>注册考试之前需要在 Linux 基金会全球官网注册一个 Linux Foundation ID（LFID）。（官网：<a href="https://myprofile.linuxfoundation.org" target="_blank" rel="noreferrer">https://myprofile.linuxfoundation.org</a>）</p><p>注意：注册 LFID 时填写 First name 和 Last name 不可为空，否则证书上的姓名将无法正确显示。First name 是名，Last name 是姓。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/9.png" alt=""></a></p><p>填写信息，点击 “Create Account” 按钮创建账号，然后再通过邮箱中的链接对账号进行验证，验证通过后完成注册流程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/10.png" alt=""></a></p><h3 id="使用考试券注册考试" tabindex="-1">使用考试券注册考试 <a class="header-anchor" href="#使用考试券注册考试" aria-label="Permalink to &quot;使用考试券注册考试&quot;">​</a></h3><p>注册后登录官网，进入 “Training &amp; Certification” 页面，点击 “Apply Registration Code” 导航按钮，进入注册考试页面。（链接：<a href="https://trainingportal.linuxfoundation.org/%EF%BC%89" target="_blank" rel="noreferrer">https://trainingportal.linuxfoundation.org/）</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/11.png" alt=""></a></p><p>输入考试券号码，点击 “Validate” 按钮，用于验证考试码的有效性，再点击 “Register” 按钮注册考试。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/12.png" alt=""></a></p><p>考试注册成功后页面跳转到首页，点击认证考试旁边的 “Start Certification” 或 “Resume” 进入Checklist 页面，从而进行预约考试过程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/13.png" alt=""></a></p><h2 id="预约-cka-考试" tabindex="-1">预约 CKA 考试 <a class="header-anchor" href="#预约-cka-考试" aria-label="Permalink to &quot;预约 CKA 考试&quot;">​</a></h2><h3 id="信息验证" tabindex="-1">信息验证 <a class="header-anchor" href="#信息验证" aria-label="Permalink to &quot;信息验证&quot;">​</a></h3><p>注册考试成功后，我们进入了 Checklist 页面。在 Checklist 页面，你需要完成清单中的要求（同意协议、确认平台、检查系统要求、阅读其他注意事项等），做完清单中的项目会自动打钩。</p><p>注意：“Verify Name” 是证书上显示的姓名，写名字全拼，名在前姓在后。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/14.png" alt=""></a></p><p>然后大约等待半小时，第四行 “Schedule an Exam” 按钮将由灰色变成橘色，点击 “Schedule”按钮便可以进入考试预约页面。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/15.png" alt=""></a></p><h3 id="预约考试时间" tabindex="-1">预约考试时间 <a class="header-anchor" href="#预约考试时间" aria-label="Permalink to &quot;预约考试时间&quot;">​</a></h3><p>进入到考试预约页面之后，可以看到“您有资格参加以下测试”的列表，点击 “CKA ChinaExam”，进入到“考试详情”页面。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/16.png" alt=""></a></p><p>可以阅读常见问题和考试说明，然后点击“继续预订”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/17.png" alt=""></a></p><p>这时进入到预定考试步骤。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/18.png" alt=""></a></p><p>检查自己的姓名和邮箱是否正确。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/19.png" alt=""></a></p><p>上传身份证照片，填写身份证号码，这里也可以先跳过，预约成功后再补。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/20.png" alt=""></a></p><p>选择国家和时区。注意：要选择中国。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/21.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/21.png" alt=""></a></p><p>页面中会展示能够选择的考试时间，你可以选择希望的考试时间。点击 “BOOK THIS TIMESLOT” 按钮确认预约考试时间。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/22.png" alt=""></a></p><p>再次点击 “Continue” 按钮确认你的考试信息，看到以下页面表示你已预约成功。同时，你的邮箱也会收到来自考试中心的确认信。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/23.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/23.png" alt=""></a></p><p>注意：由于 CKA 考试需要使用你的本地电脑，所以你需要提前检查当前电脑是否满足考试环境的兼容性要求。</p><p>预约成功后，再次进入考试中心网站，可以看到你的预约时间，可以点击 “Cancel orReschedule” 链接取消或重新安排考试时间。</p><p>注意：有很多之前考过的同学反映网络有点卡，建议你预约晚上或早上网络情况相对好的时间。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/24.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/24.png" alt=""></a></p><h3 id="常见预约问题" tabindex="-1">常见预约问题 <a class="header-anchor" href="#常见预约问题" aria-label="Permalink to &quot;常见预约问题&quot;">​</a></h3><p>问：预约考试后可以修改考试时间吗？</p><p>答：如果需要修改或取消考试时间，必须在考试开始前 24 小时完成，否则你将必须参加考试或弃权。</p><p>问：为什么在预约考试后很久也没收到确认通知邮件？</p><p>答：确认通知邮件是系统自动发送的。如果在预约考试后没有收到确认通知邮件，请查看是否在垃圾邮件中。另外，你可以取消并再次预约考试，系统会再次自动发送通知邮件。</p><h2 id="考试前注意事项" tabindex="-1">考试前注意事项 <a class="header-anchor" href="#考试前注意事项" aria-label="Permalink to &quot;考试前注意事项&quot;">​</a></h2><ol><li><p>考试前准备好身份证件，考试链接地址<a href="https://trainingportal.linuxfoundation.org/learn/dashboard%E3%80%82" target="_blank" rel="noreferrer">https://trainingportal.linuxfoundation.org/learn/dashboard。</a></p></li><li><p>考试前 30 分钟就可以点击“启动考试”按钮进入考试流程，这样你可以先进行考前检查过程，即考生拍照、上传照片，环境检查等，然后进入监考官审核环节，电脑上会弹出监考官的聊天窗口，按照监考官的要求去做就行。</p></li><li><p>电脑使用 Windows 和 Mac 等操作系统都可以，如果电脑没有摄像头，需要自己配一个摄像头，监考官通过摄像头来远程监考。</p></li><li><p>考试环境尽量封闭，不要摆放太多东西，不能有其他人在旁边，不能使用双屏。</p></li><li><p>考试中使用官方提供的 PSI 独立软件考试，需要关闭其他所有软件。我之前考试就遇到没有关闭电脑上的一个远程连接应用，导致无法通过检查。</p></li><li><p>如果遇到任何问题，不要着急，可以跟监考官沟通，甚至可以暂停推迟考试。</p></li><li><p>所有的检测完成后，进入到考试界面，才开始计算考试正式时间，所以就算之前各种检查的时间超过预定考试开始时间，考试时间也会自动顺延。</p></li></ol><h2 id="考试中注意事项" tabindex="-1">考试中注意事项 <a class="header-anchor" href="#考试中注意事项" aria-label="Permalink to &quot;考试中注意事项&quot;">​</a></h2><p>CKA 考试要求下载和使用官方提供的 PSI 考试软件。打开 PSI 考试软件，这是一个类似的考试界面，你一看就能明白。题目在左侧，右侧是答题区域，同时最右侧还有一个窗口，只能访问 K8s 官方技术文档。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/25.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/18/25.png" alt=""></a></p><p>在考试中需要注意：</p><ol><li><p>考试时，不能访问外网，但是每道考题会有一个提示链接，点击后在右侧窗口中可以访问K8s 的官方技术文档，你可以参考文档。</p></li><li><p>考试中，为了速度快，可以尽量使用 kubectl 命令，如果需要写 YAML 文件，也可以在官方技术文档中复制粘贴过来。</p></li><li><p>考试时间比较充裕，只要你掌握课程里的知识点和熟练真题，就可以答完。如果遇到有不太会的题目，也可以先标记，继续做其他题目，最后再来做标记题目。</p></li><li><p>全部考题答完就可以点击结束考试交卷。通常 1 天就可以出结果，如果没考过还可以申请一次重考（retake）。</p></li><li><p>考试过程中，监考官会一直通过摄像头监考，如果发现有异样，会弹出聊天窗口警告。你如果在考试过程中有什么需要，也可以通过聊天窗口告诉监考官，比如想喝水休息一下。</p></li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天我给你把报名 CKA 认证考试的流程和考试的注意事项从头到尾梳理了一遍，你可以按照课程内容自行报名和预约考试。</p>',82)])])}const p=t(a,[["render",s]]);export{g as __pageData,p as default};
